import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useLocation } from 'react-router-dom';
import styles from '../css/chat.module.css';

const Chat = () => {
  const location = useLocation();
  const { personality, name: chatbotName = '챗봇' } = location.state || {};
  const [userInput, setUserInput] = useState('');
  const [currentDateTime, setCurrentDateTime] = useState('');
  const [error, setError] = useState(null);
  const [isRecording, setIsRecording] = useState(false);
  const [isProcessingResponse, setIsProcessingResponse] = useState(false);
  const [audioHtml, setAudioHtml] = useState(null);
  const [messages, setMessages] = useState([]);
  const [alertTime, setAlertTime] = useState(null); // 알림 시간
  const chatEndRef = useRef(null);
  const mediaRecorderRef = useRef(null);
  const audioChunksRef = useRef([]);
  const inputRef = useRef(null);

  const getCurrentDateTime = () => {
    const now = new Date();
    const date = now.toLocaleDateString('ko-KR', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      weekday: 'long',
    });
    const time = now.toLocaleTimeString('ko-KR', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: false,
    });
    return `${date} ${time}`;
  };

  // 알림 시간을 5분 전으로 설정
  const setAlertTimeAt = (time) => {
    const targetTime = new Date(time);
    targetTime.setMinutes(targetTime.getMinutes() - 5); // 5분 전으로 설정
    setAlertTime(targetTime);
  };

  // 시간 추출 함수 (정규 표현식)
  const extractTimeFromMessage = (message) => {
    const timeRegex = /(\d{1,2})시\s*(\d{1,2})?분?/; // "4시 40분" 또는 "6시"와 같은 형식
    const match = message.match(timeRegex);

    if (match) {
      const hours = parseInt(match[1], 10);
      const minutes = match[2] ? parseInt(match[2], 10) : 0;
      const now = new Date();
      now.setHours(hours);
      now.setMinutes(minutes);
      now.setSeconds(0); // 초는 0으로 설정

      return now;
    }

    return null; // 시간 형식이 없으면 null 반환
  };

  // 알림 확인 및 알림 트리거
  useEffect(() => {
    const interval = setInterval(() => {
      const now = new Date();
      if (alertTime && now >= alertTime) {
        alert('알림: 예정된 시간 5분 전입니다!');
        setAlertTime(null); // 알림을 한 번만 표시하도록 처리
      }
    }, 60000); // 1분마다 체크

    return () => clearInterval(interval); // 컴포넌트가 언마운트될 때 interval을 정리
  }, [alertTime]);

  // 채팅 기록과 시간 업데이트
  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentDateTime(getCurrentDateTime());
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  // 메시지 보내기
  const handleSendMessage = async () => {
    if (isRecording || isProcessingResponse || userInput.trim() === '') return;

    const sentTime = getCurrentDateTime();
    setMessages((prevMessages) => [
      ...prevMessages,
      { sender: '사용자', message: userInput, time: sentTime },
    ]);

    // 메시지에서 시간 추출
    const extractedTime = extractTimeFromMessage(userInput);
    if (extractedTime) {
      setAlertTimeAt(extractedTime); // 알림 시간 설정
    }

    setUserInput('');

    try {
      setIsProcessingResponse(true);
      const response = await fetch(`${process.env.REACT_APP_API_URL}/chat`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          chatbotName: chatbotName,
          user_input: userInput,
          personality: personality,
        }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || '서버 응답 오류');
      }

      const data = await response.json();
      const chatbotMessage = data.response;
      const newAudioHtml = data.audio_html;

      setMessages((prevMessages) => [
        ...prevMessages,
        { sender: chatbotName, message: chatbotMessage, time: getCurrentDateTime() },
      ]);

      setAudioHtml(newAudioHtml);
    } catch (error) {
      console.error('Error fetching chatbot response:', error);
      if (error.message.includes('부적절한 내용')) {
        alert('부적절한 내용은 사용할 수 없습니다. 다시 입력해주세요.');
        setMessages((prevMessages) => prevMessages.slice(0, -1));  // 마지막 메시지 제거
      } else {
        setError(error.message);
      }
    } finally {
      setIsProcessingResponse(false);
    }
  };

  // 사용자가 알림 설정을 할 때 예시로 시간 입력
  const handleSetAlert = () => {
    const inputTime = '2025-01-21T16:40:00'; // 예시로 4시 40분으로 설정
    setAlertTimeAt(inputTime);
  };

  return (
    <div className={styles.chatContainer}>
      <div className={styles.chatDataTime}>
        <strong>{currentDateTime}</strong>
      </div>
      <div className={styles.chatHistory}>
        {messages.map((msg, index) => (
          <div
            key={index}
            className={msg.sender === '사용자' ? styles.chatMessageUser : styles.chatMessageChatbot}
          >
            <strong>{msg.sender === '사용자' ? '사용자' : chatbotName}:</strong>
            <div>{msg.message}</div>
            <div className={msg.sender === '사용자' ? styles.chatTimeUser : styles.chatTimeChatbot}>
              <em>{msg.time}</em>
            </div>
          </div>
        ))}
        <div ref={chatEndRef} />
      </div>
      <div className={styles.chatInputArea}>
        <input
          ref={inputRef}  // 입력 필드에 ref 추가
          type="text"
          value={userInput}
          onChange={(e) => setUserInput(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
        />
        <button
          className={styles.chatSendButton}
          onClick={handleSendMessage}
        >
          전송
        </button>
        <button
          className={styles.voiceButton}
          onClick={isRecording ? stopRecording : startRecording}
        >
          {isRecording ? '녹음 중지' : '음성 인식 시작'}
        </button>
      </div>
      {displayErrorMessage()}
      {!isRecording && !isProcessingResponse && audioHtml && userInput.trim() === '' && (
        <div dangerouslySetInnerHTML={{ __html: audioHtml }} />
      )}
    </div>
  );
};

export default Chat;
